import 'dart:async';
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/src/providers/proxy_connector.dart';
import 'package:http/http.dart' as http;
import 'package:http/testing.dart';
import 'package:test/test.dart';

import 'agent_cli_test_support.dart';

/// The DIAL setup flows fetch `<baseUrl>/models` with a 15s network
/// timeout (provider_models.dart). Tests must never touch the network:
/// this client answers 404 so the fetch lands in the same swallowed
/// `return const []` path — instantly, with identical semantics.
final _kNoModelsFetch = MockClient(
  (request) async => http.Response('not found', 404),
);

void main() {
  late MemoryExecutionEnv env;
  late FakeCliIO io;

  setUp(() {
    env = MemoryExecutionEnv(cwd: '/work');
    io = FakeCliIO();
  });

  tearDown(() => io.close());

  AgentCli cliFor(
    StreamFunction streamFunction, {
    Model model = testModel,
    ExecutionEnv? envOverride,
    bool Function(String name)? envVarIsSet,
    String? Function(String name)? envVarValue,
    Future<List<String>> Function(String baseUrl, {required String apiKey})?
    modelsFetcher,
    http.Client? modelsHttpClient,
    Map<String, ProviderNetworkConfig>? providerNetworks,
    Future<void> Function(String providerKind, String apiKey)?
    onProviderChanged,

      await io.out.waitUntilContains('DIAL API key');
      io.sendLine('dial-key-2');
      await io.out.waitUntilContains('deployment (model id)');
      io.sendLine('gpt-4o');
      await io.out.waitUntilContains('provider name');
      io.sendLine('dial-work');
      await io.out.waitUntilContains('switched provider to dial');
      io.sendLine('/exit');
      await run;

      final entry = registry.find('dial-work');
      expect(entry, isNotNull);
      // Custom name → name-scoped slot, NOT the host-scoped one.
      expect(entry!.keyName, 'FA_KEY_AI_PROXY_LAB_EPAM_COM_DIAL_WORK');
      expect(store.map[entry.keyName], 'dial-key-2');
      expect(store.map['FA_KEY_AI_PROXY_LAB_EPAM_COM'], isNull);
    });

    test('/provider dial setup rejects extra args', () async {
      final fake = FakeStreamFunction([textTurn('ok')]);
      final cli = cliFor(fake.call);
      final run = cli.run();

      io.sendLine('/provider dial setup extra');
      await io.out.waitUntilContains('usage: /provider dial setup');
      io.sendLine('/exit');
      await run;
    });

    test('/provider openrouter shows auth-method picker', () async {
      final fake = FakeStreamFunction([textTurn('ok')]);
      final cli = cliFor(fake.call, envVarValue: (_) => null);
      final run = cli.run();

      io.sendLine('/provider openrouter');
      await io.out.waitUntilContains('OpenRouter sign-in method');
      io.sendLine('2'); // API key option
      await io.out.waitUntilContains('OpenRouter API key:');
      io.sendLine('sk-or-test-key');
      await io.out.waitUntilContains('switched provider to openrouter');
      io.sendLine('/exit');
      await run;

      expect(io.out.toString(), contains('OpenRouter sign-in method'));
      expect(io.out.toString(), contains('key: provided'));
    });

    test('/provider openrouter api-key connect saves a named entry', () async {
      // The API-key branch produces the same saved-entry shape as the OAuth
      // connect — provider-name step included.
      final fake = FakeStreamFunction([textTurn('ok')]);
      final store = FakeSecureKeyStore();
